SELECT a.id, a.name, a.category_id, ac.name AS category_name, a.description, a.address, a.city, a.longitude, a.latitude, a.open_time, a.ticket_price, COALESCE(rs.avg_rating, 0) AS rating, COALESCE(rs.rating_count, 0) AS rating_count, a.create_time, CASE WHEN f.id IS NOT NULL THEN 1 ELSE 0 END AS is_favorited FROM attraction a LEFT JOIN attraction_category ac ON a.category_id = ac.id LEFT JOIN ( SELECT attraction_id, ROUND(AVG(overall_score), 1) AS avg_rating, COUNT(*) AS rating_count FROM attraction_rating WHERE overall_score > 0 GROUP BY attraction_id ) rs ON a.id = rs.attraction_id LEFT JOIN favorite f ON a.id = f.item_id AND f.item_type = 'attraction' AND f.user_id = #{userId} AND f.deleted = 0 WHERE a.deleted = 0 AND a.audit_status = 1
AND a.name LIKE CONCAT('%', #{keyword}, '%')
AND a.category_id = #{categoryId}
AND a.province IN
#{provinceItem}
ORDER BY a.rating DESC, a.create_time DESC

SELECT a.id, a.name, a.category_id, ac.name AS category_name, a.description, a.address, a.city, a.province, a.district, a.scenic_level, a.longitude, a.latitude, a.open_time, a.ticket_price, a.charge_type, a.suggested_duration, a.best_months, a.scene_type, COALESCE(rs.avg_rating, 0) AS rating, COALESCE(rs.rating_count, 0) AS rating_count, a.view_count, a.favorite_count, a.contact_phone, a.official_website, a.seasonal_status, a.seasonal_note, a.create_time, CASE WHEN f.id IS NOT NULL THEN 1 ELSE 0 END AS is_favorited, CASE WHEN uf.id IS NOT NULL THEN 1 ELSE 0 END AS is_visited FROM attraction a LEFT JOIN attraction_category ac ON a.category_id = ac.id LEFT JOIN ( SELECT attraction_id, ROUND(AVG(overall_score), 1) AS avg_rating, COUNT(*) AS rating_count FROM attraction_rating WHERE overall_score > 0 GROUP BY attraction_id ) rs ON a.id = rs.attraction_id LEFT JOIN favorite f ON a.id = f.item_id AND f.item_type = 'attraction' AND f.user_id = #{userId} AND f.deleted = 0 LEFT JOIN user_footprint uf ON a.id = uf.attraction_id AND uf.user_id = #{userId} WHERE a.deleted = 0 AND a.audit_status = 1
AND a.name LIKE CONCAT('%', #{query.keyword}, '%')
AND a.category_id = #{query.categoryId}
AND a.province = #{query.province}
AND a.city = #{query.city}
AND a.district = #{query.district}
AND FIND_IN_SET(#{query.scenicLevel}, a.scenic_level) > 0
AND FIND_IN_SET(#{query.sceneType}, a.scene_type) > 0
AND a.ticket_price >= #{query.minPrice}
AND a.ticket_price <= #{query.maxPrice}
AND a.suggested_duration = #{query.suggestedDuration}
AND FIND_IN_SET(#{query.bestMonth}, a.best_months) > 0
AND FIND_IN_SET(#{query.bestSeason}, a.best_months) > 0
ORDER BY a.id ASC
ORDER BY a.id DESC
ORDER BY (a.view_count * 0.4 + a.favorite_count * 0.6) DESC
ORDER BY COALESCE(rs.avg_rating, 0) DESC, a.view_count DESC
ORDER BY ST_Distance_Sphere( POINT(a.longitude, a.latitude), POINT(#{query.userLng}, #{query.userLat}) ) ASC
ORDER BY a.ticket_price ASC
ORDER BY a.ticket_price DESC
ORDER BY a.create_time DESC

mapper.update:
UPDATE attraction
SET view_count = view_count + 1
WHERE id = #{id}

UPDATE attraction
SET favorite_count = favorite_count + #{delta}
WHERE id = #{id}
